Object.assign(STRINGS.de, { hn_hu_small_lkw: 'Lkw bis 3,5 t: HU-Intervall hängt von weiteren Merkmalen ab – nicht automatisch berechnet.', hn_hu_conflict: 'Widerspruch: Nachweis nennt {doc}, Berechnung aus letzter HU ergibt {calc}.', hn_hu_none: 'Keine durchgeführte HU belegt.', hn_hu_no_class: 'Fahrzeugklasse (zulässige Gesamtmasse) fehlt – HU-Intervall nicht bestimmbar.', hn_hu_bad_result: 'Letzte HU mit erheblichen/gefährlichen Mängeln – Nachprüfung belegen.', hn_sp_no_class: 'Zulässige Gesamtmasse fehlt – SP-Pflicht nicht bestimmbar.', hn_sp_not_req_lkw: 'Lkw bis 7,5 t zGM: keine Sicherheitsprüfung.', hn_sp_not_req_trailer: 'Anhänger bis 10 t zGM: keine Sicherheitsprüfung.', hn_sp_doc_no_hu: 'Fälligkeit laut Nachweis (Plakette/Beleg); keine durchgeführte HU belegt.', hn_sp_first_prognosis: 'Erste SP {m} Monate nach Erstzulassung (Prognose; verbindlich 6 Monate nach der dann letzten HU).', hn_sp_no_hu: 'Keine durchgeführte HU belegt – SP-Frist (6 Monate nach HU) nicht bestimmbar.', hn_sp_starts_later: 'SP-Pflicht beginnt erst; erste SP {m} Monate nach Erstzulassung (Prognose).', hn_sp_from_sp_evidence: 'Erstzulassung fehlt; SP-Pflicht aus vorhandenem SP-Nachweis abgeleitet.', hn_sp_doc_matches: 'Fälligkeit laut Nachweis (Plakette/Beleg) stimmt mit der Berechnung überein.', hn_sp_start_unclear: 'Erstzulassung fehlt und keine SP belegt – Beginn der SP-Pflicht unklar.', hn_sp_prev_open: 'SP fällig {due} (nach HU {hu}) nicht belegt – die spätere HU ersetzt sie nicht.', hn_sp_cycle_done: 'SP für diesen Zyklus durchgeführt ({date}). Nächste SP 6 Monate nach der nächsten HU.', hn_sp_too_early: 'SP am {date} vor dem zulässigen Zeitraum (ab {from}) – Frist ungeklärt, Prüfprotokoll prüfen.', hn_sp_conflict: 'Widerspruch: Nachweis nennt {doc}, Berechnung (6 Monate nach HU {hu}) ergibt {calc}.' });
Object.assign(STRINGS.uk, { hn_hu_small_lkw: 'Вантажівка до 3,5 т: інтервал HU залежить від інших ознак – не розраховується автоматично.', hn_hu_conflict: 'Розбіжність: у підтвердженні вказано {doc}, розрахунок від останнього HU дає {calc}.', hn_hu_none: 'Немає підтвердженого проведеного HU.', hn_hu_no_class: 'Не вказано клас ТЗ (дозволена повна маса) – інтервал HU визначити неможливо.', hn_hu_bad_result: 'Останній HU зі значними/небезпечними дефектами – підтвердіть повторну перевірку.', hn_sp_no_class: 'Не вказано дозволену повну масу – обов’язок SP визначити неможливо.', hn_sp_not_req_lkw: 'Вантажівка до 7,5 т повної маси: SP не потрібна.', hn_sp_not_req_trailer: 'Причіп до 10 т повної маси: SP не потрібна.', hn_sp_doc_no_hu: 'Строк згідно з підтвердженням (наліпка/документ); проведений HU не підтверджено.', hn_sp_first_prognosis: 'Перша SP через {m} міс. після першої реєстрації (прогноз; обов’язково 6 міс. після останнього на той час HU).', hn_sp_no_hu: 'Немає підтвердженого HU – строк SP (6 міс. після HU) визначити неможливо.', hn_sp_starts_later: 'Обов’язок SP ще не почався; перша SP через {m} міс. після першої реєстрації (прогноз).', hn_sp_from_sp_evidence: 'Немає дати першої реєстрації; обов’язок SP виведено з наявного підтвердження SP.', hn_sp_doc_matches: 'Строк згідно з підтвердженням (наліпка/документ) збігається з розрахунком.', hn_sp_start_unclear: 'Немає дати першої реєстрації і підтвердженої SP – початок обов’язку SP неясний.', hn_sp_prev_open: 'SP зі строком {due} (після HU {hu}) не підтверджено – пізніший HU її не замінює.', hn_sp_cycle_done: 'SP для цього циклу проведено ({date}). Наступна SP через 6 міс. після наступного HU.', hn_sp_too_early: 'SP {date} проведено до допустимого періоду (з {from}) – строк неясний, перевірте протокол.', hn_sp_conflict: 'Розбіжність: у підтвердженні вказано {doc}, розрахунок (6 міс. після HU {hu}) дає {calc}.' });
