Object.assign(STRINGS.de, { defect_stats: 'Mängelstatistik Kontrollen', defect_stats_hint: 'Welche Prüfpunkte wie oft als Mangel erfasst wurden – aus Abfahrtskontrollen und Kontrollen nach Reparatur. Hilft, wiederkehrende Schwachstellen und Fahrzeuge mit vielen Mängeln zu erkennen.', period: 'Zeitraum', check_kind: 'Art der Kontrolle', checks_done: 'Kontrollen', checks_with_defects: 'mit Mangel', defect_items: 'Mängel', defects_by_item: 'Nach Prüfpunkt', defects_by_vehicle: 'Nach Fahrzeug', no_defects_period: 'Keine Mängel im Zeitraum.', last_check_any: 'Letzte Kontrolle', defect_stats_rule: 'Nur gespeicherte Kontrollen dieser Umgebung; ruhende Fahrzeuge sind ausgenommen. Ohne Personenbezug. Ein Mangel zählt je Kontrolle und Prüfpunkt einmal.' });
Object.assign(STRINGS.uk, { defect_stats: 'Статистика дефектів перевірок', defect_stats_hint: 'Які пункти перевірки як часто позначено дефектом – з перевірок перед виїздом і перевірок після ремонту. Допомагає побачити повторювані слабкі місця і транспорт з багатьма дефектами.', period: 'Період', check_kind: 'Вид перевірки', checks_done: 'Перевірки', checks_with_defects: 'з дефектом', defect_items: 'Дефекти', defects_by_item: 'За пунктом перевірки', defects_by_vehicle: 'За транспортом', no_defects_period: 'За період дефектів немає.', last_check_any: 'Остання перевірка', defect_stats_rule: 'Лише збережені перевірки цього середовища; транспорт, виключений зі звітів, не враховується. Без персональних даних. Дефект рахується один раз на перевірку і пункт.' });
Object.assign(STRINGS.en, { defect_stats: 'Check defect statistics', defect_stats_hint: 'Which check items were recorded as defects and how often – from pre-trip checks and post-repair checks. Helps to spot recurring weak points and vehicles with many defects.', period: 'Period', check_kind: 'Type of check', checks_done: 'Checks', checks_with_defects: 'with defect', defect_items: 'Defects', defects_by_item: 'By check item', defects_by_vehicle: 'By vehicle', no_defects_period: 'No defects in this period.', last_check_any: 'Last check', defect_stats_rule: 'Only stored checks of this environment; dormant vehicles are excluded. No personal data. A defect counts once per check and item.' });
Object.assign(STRINGS.de, { vi_prev_same: 'Gleicher Prüfpunkt kürzlich repariert', vi_prev_same_hint: 'Derselbe Mangel wurde an diesem Fahrzeug in den 90 Tagen vor dieser Meldung schon einmal behoben – Ursache prüfen (z. B. Nacharbeit, Teilequalität).' });
Object.assign(STRINGS.uk, { vi_prev_same: 'Той самий пункт нещодавно ремонтували', vi_prev_same_hint: 'Цей самий дефект на цьому транспорті вже усували протягом 90 днів до цього повідомлення – перевірте причину (наприклад, доопрацювання, якість запчастин).' });
