Object.assign(STRINGS.de, { days_one: 'Tag', days_other: 'Tage', kpi_downtime: 'Ausfall', vd_title: 'Ausfall je Monat (letzte {n})', vd_total: 'Summe', vd_rule: 'Werkstatt-Übernahme bis Freigabe (offene Aufträge bis jetzt) und Zeit mit Sicherheitssperre zusammen; mehrere Aufträge gleichzeitig zählen einmal. Verfügbarkeit = Anteil der Stunden des Monats ohne Ausfall (ab Anlage des Fahrzeugs in der App, laufender Monat bis jetzt). Nur gespeicherte Zeitpunkte, nichts geschätzt.' });
Object.assign(STRINGS.uk, { days_one: 'день', days_few: 'дні', days_many: 'днів', days_other: 'дня', kpi_downtime: 'Простій', vd_title: 'Простій за місяцями (останні {n})', vd_total: 'Разом', vd_rule: 'Від прийняття майстернею до допуску (відкриті замовлення – до зараз) разом із часом блокування безпеки; кілька замовлень одночасно рахуються один раз. Готовність = частка годин місяця без простою (від внесення транспорту в застосунок, поточний місяць – до зараз). Лише збережені часові мітки, без оцінок.' });
Object.assign(STRINGS.en, { days_one: 'day', days_other: 'days', kpi_downtime: 'Downtime', vd_title: 'Downtime per month (last {n})', vd_total: 'Total', vd_rule: 'Workshop takeover until release (open orders until now) plus time with safety lock; several orders at the same time count once. Availability = share of the month’s hours without downtime (from when the vehicle was added to the app, current month until now). Stored timestamps only, nothing estimated.' });
