Object.assign(STRINGS.de, { kpi_av: 'Technische Verfügbarkeit', kpi_av_short: 'Verfügbarkeit', kpi_av_of: 'der Fahrzeugstunden verfügbar', kpi_av_line: 'Fahrzeuge: {n} · Ausfall gesamt: {d}', kpi_av_lowest: 'Geringste Verfügbarkeit im Zeitraum', kpi_av_none: 'Im Zeitraum kein Ausfall erfasst.', kpi_av_rule: 'Ausfall = Werkstatt-Übernahme bis technische Freigabe bzw. Ablehnung (offen bis jetzt) und Zeit mit Sicherheitssperre, je Fahrzeug Überschneidungen einmal, auf den Zeitraum zugeschnitten (auch Vorgänge aus früheren Monaten). Fahrzeugstunden = aktive Fahrzeuge laut Stamm (ohne ruhende) vom Monatsbeginn bzw. ihrer Anlage bis Monatsende bzw. jetzt. Werkstattaufenthalte ohne Vorgang in der App sind nicht erfasst – die Quote ist daher eine Obergrenze.', kpi_av_site: 'Mit Werkstattfilter wird keine Verfügbarkeit berechnet – sie gilt für das ganze Fahrzeug, nicht für eine Werkstatt.' });
