Object.assign(STRINGS.en, { kpi_av: 'Technical availability', kpi_av_short: 'Availability', kpi_av_of: 'of vehicle hours available', kpi_av_line: 'Vehicles: {n} · Total downtime: {d}', kpi_av_lowest: 'Lowest availability in the period', kpi_av_none: 'No downtime recorded in the period.', kpi_av_rule: 'Downtime = workshop takeover until technical release or rejection (open until now) plus time under safety lock, overlaps counted once per vehicle, clipped to the period (including cases from earlier months). Vehicle hours = active vehicles in the master data (excluding dormant ones) from the start of the month or when they were added until the end of the month or now. Workshop stays without a case in the app are not recorded – the figure is therefore an upper bound.', kpi_av_site: 'With a workshop filter no availability is calculated – it applies to the whole vehicle, not to one workshop.' });
