Object.assign(STRINGS.de, { tf_admin_hint: '{n} aktive(s) Konto/Konten mit Verwaltungsrechten (Inhaber/Fuhrparkleitung, Betrieb) ohne Zwei-Faktor-Anmeldung. Empfehlung: unter Mehr → Mein Konto einschalten.', tf_title: 'Zwei-Faktor-Anmeldung', tf_on: 'eingeschaltet seit {d}', tf_off: 'ausgeschaltet', tf_intro: 'Zusätzlich zum Passwort ein 6-stelliger Code aus einer Authenticator-App auf Ihrem Handy (z. B. die vorinstallierte Passwort-App). Schützt das Konto, falls das Passwort bekannt wird. Freiwillig; die App versendet dafür nichts.', tf_start: 'Einrichten', tf_pw: 'Zur Bestätigung: Ihr Passwort', tf_scan: 'QR-Code mit der Authenticator-App scannen (oder den Schlüssel von Hand eingeben), dann den angezeigten 6-stelligen Code eingeben.', tf_key: 'Schlüssel', tf_code: 'Code aus der App (6 Ziffern)', tf_enable: 'Einschalten', tf_rc_title: 'Ersatzcodes – jetzt sichern', tf_rc_hint: 'Jeder Code gilt genau einmal, falls das Handy fehlt. Ausdrucken oder sicher aufbewahren – sie werden nur jetzt angezeigt.', tf_others_ended: 'Andere Anmeldungen dieses Kontos wurden beendet.', tf_rc_left: 'Ersatzcodes übrig: {n}', tf_rc_new: 'Neue Ersatzcodes erzeugen', tf_rc_new_hint: 'Die bisherigen Ersatzcodes werden ungültig.', tf_disable: 'Ausschalten', tf_code_or_rc: 'Code aus der App oder Ersatzcode', tf_login_hint: 'Bitte den 6-stelligen Code aus der Authenticator-App eingeben. Handy nicht dabei? Einen Ersatzcode eingeben.', tf_confirm: 'Bestätigen', tf_back: 'Zurück zur Anmeldung', tf_rc_used: 'Mit Ersatzcode angemeldet – noch {n} übrig. Neue Ersatzcodes unter Mehr → Mein Konto → Zwei-Faktor-Anmeldung.', tf_reset: 'Zwei-Faktor zurücksetzen', tf_reset_confirm: 'Zwei-Faktor-Anmeldung von {name} zurücksetzen (z. B. Handy verloren)? Alle Anmeldungen werden beendet; danach genügt das Passwort, und die Person kann die Zwei-Faktor-Anmeldung neu einrichten.', tf_chip: '2FA', tf_cancel: 'Abbrechen', err_wrong_password: 'Passwort falsch.', err_totp_invalid: 'Code falsch oder abgelaufen.', err_totp_expired: 'Anmeldung abgelaufen. Bitte Benutzername und Passwort erneut eingeben.', err_totp_already: 'Zwei-Faktor-Anmeldung ist bereits eingeschaltet.', err_totp_off: 'Zwei-Faktor-Anmeldung ist nicht eingeschaltet.', err_totp_no_setup: 'Bitte zuerst „Einrichten“ wählen.', help_login2fa_t: 'Anmeldung schützen (Zwei-Faktor)', help_login2fa_s: 'Mehr → Mein Konto → Zwei-Faktor-Anmeldung → Einrichten: Passwort eingeben, QR-Code mit einer Authenticator-App auf dem Handy scannen, den 6-stelligen Code eingeben → Einschalten.|Danach fragt die App nach dem Passwort zusätzlich den aktuellen Code aus der Authenticator-App ab. Ein Code gilt 30 Sekunden und nur einmal; geht die Uhr des Handys falsch, passt der Code nicht.|Die angezeigten Ersatzcodes ausdrucken oder sicher aufbewahren: Jeder gilt einmal, wenn das Handy fehlt. Neue Ersatzcodes gibt es jederzeit unter Mein Konto (die alten werden dann ungültig).|Handy verloren und keine Ersatzcodes mehr? Der Inhaber kann die Zwei-Faktor-Anmeldung unter Mehr → Benutzer zurücksetzen; dabei werden alle Anmeldungen beendet. Codes und Ersatzcodes niemals weitergeben.|Neues Gerät: Meldet sich jemand mit Ihrem Konto auf einem Gerät an, das für Ihr Konto neu ist, erhalten Sie den Hinweis „Neue Anmeldung auf einem anderen Gerät“ (Gerät und Uhrzeit). Waren Sie das nicht: unter Mein Konto → Meine Anmeldungen (Geräte) das Gerät abmelden und das Passwort ändern. Die erste Anmeldung überhaupt und Anmeldungen auf bekannten Geräten lösen keinen Hinweis aus. Darunter stehen die bekannten Geräte: ein altes oder verkauftes Handy dort „Vergessen“ – meldet sich danach jemand darauf an, kommt wieder der Hinweis.' });
Object.assign(STRINGS.uk, { tf_admin_hint: 'Активних акаунтів з правами керування (власник/керівник автопарку, робота) без двофакторного входу: {n}. Рекомендація: увімкнути в Більше → Мій акаунт.', tf_title: 'Двофакторний вхід', tf_on: 'увімкнено з {d}', tf_off: 'вимкнено', tf_intro: 'Окрім пароля – 6-значний код із застосунку-автентифікатора на вашому телефоні (напр. вбудований застосунок паролів). Захищає акаунт, якщо пароль стане відомим. Добровільно; застосунок нічого для цього не надсилає.', tf_start: 'Налаштувати', tf_pw: 'Для підтвердження: ваш пароль', tf_scan: 'Скануйте QR-код застосунком-автентифікатором (або введіть ключ вручну), потім введіть показаний 6-значний код.', tf_key: 'Ключ', tf_code: 'Код із застосунку (6 цифр)', tf_enable: 'Увімкнути', tf_rc_title: 'Резервні коди – збережіть зараз', tf_rc_hint: 'Кожен код діє лише один раз, якщо телефона немає під рукою. Роздрукуйте або збережіть у надійному місці – вони показуються лише зараз.', tf_others_ended: 'Інші входи цього акаунта завершено.', tf_rc_left: 'Залишилось резервних кодів: {n}', tf_rc_new: 'Створити нові резервні коди', tf_rc_new_hint: 'Попередні резервні коди стануть недійсними.', tf_disable: 'Вимкнути', tf_code_or_rc: 'Код із застосунку або резервний код', tf_login_hint: 'Введіть 6-значний код із застосунку-автентифікатора. Телефона немає? Введіть резервний код.', tf_confirm: 'Підтвердити', tf_back: 'Назад до входу', tf_rc_used: 'Вхід із резервним кодом – залишилось {n}. Нові резервні коди: Більше → Мій акаунт → Двофакторний вхід.', tf_reset: 'Скинути двофакторний вхід', tf_reset_confirm: 'Скинути двофакторний вхід для {name} (напр. втрачено телефон)? Усі входи буде завершено; далі достатньо пароля, і особа зможе налаштувати двофакторний вхід знову.', tf_chip: '2FA', tf_cancel: 'Скасувати', err_wrong_password: 'Неправильний пароль.', err_totp_invalid: 'Неправильний або прострочений код.', err_totp_expired: 'Час входу минув. Введіть ім’я користувача та пароль ще раз.', err_totp_already: 'Двофакторний вхід уже увімкнено.', err_totp_off: 'Двофакторний вхід не увімкнено.', err_totp_no_setup: 'Спочатку виберіть «Налаштувати».', help_login2fa_t: 'Захист входу (двофакторний)', help_login2fa_s: 'Більше → Мій акаунт → Двофакторний вхід → Налаштувати: введіть пароль, скануйте QR-код застосунком-автентифікатором на телефоні, введіть 6-значний код → Увімкнути.|Після цього застосунок окрім пароля запитує актуальний код із автентифікатора. Код діє 30 секунд і лише один раз; якщо годинник телефона неточний, код не підійде.|Роздрукуйте або надійно збережіть показані резервні коди: кожен діє один раз, якщо телефона немає. Нові резервні коди можна створити будь-коли в «Мій акаунт» (старі тоді стають недійсними).|Телефон втрачено, а резервних кодів немає? Власник може скинути двофакторний вхід у Більше → Користувачі; при цьому всі входи завершуються. Ніколи нікому не передавайте коди.|Новий пристрій: якщо хтось входить у ваш акаунт на пристрої, новому для вашого акаунта, ви отримаєте сповіщення «Новий вхід на іншому пристрої» (пристрій і час). Якщо це були не ви: у «Мій акаунт → Мої входи (пристрої)» вийдіть на цьому пристрої та змініть пароль. Перший вхід і входи на відомих пристроях сповіщення не викликають. Нижче показано відомі пристрої: старий чи проданий телефон там «Забути» – якщо хтось потім увійде на ньому, сповіщення знову надійде.' });
Object.assign(STRINGS.en, { tf_admin_hint: '{n} active account(s) with admin rights (owner/fleet management, production) without two-factor sign-in. Recommendation: turn it on under More → My account.', tf_title: 'Two-factor sign-in', tf_on: 'on since {d}', tf_off: 'off', tf_intro: 'In addition to the password, a 6-digit code from an authenticator app on your phone (e.g. the built-in password app). Protects the account if the password becomes known. Optional; the app sends nothing for this.', tf_start: 'Set up', tf_pw: 'To confirm: your password', tf_scan: 'Scan the QR code with the authenticator app (or enter the key by hand), then enter the 6-digit code shown.', tf_key: 'Key', tf_code: 'Code from the app (6 digits)', tf_enable: 'Turn on', tf_rc_title: 'Recovery codes – save them now', tf_rc_hint: 'Each code works exactly once if your phone is not at hand. Print them or keep them safe – they are shown only now.', tf_others_ended: 'Other sign-ins of this account have been ended.', tf_rc_left: 'Recovery codes left: {n}', tf_rc_new: 'Create new recovery codes', tf_rc_new_hint: 'The previous recovery codes become invalid.', tf_disable: 'Turn off', tf_code_or_rc: 'Code from the app or recovery code', tf_login_hint: 'Please enter the 6-digit code from your authenticator app. Phone not at hand? Enter a recovery code.', tf_confirm: 'Confirm', tf_back: 'Back to sign-in', tf_rc_used: 'Signed in with a recovery code – {n} left. New recovery codes: More → My account → Two-factor sign-in.', tf_reset: 'Reset two-factor', tf_reset_confirm: 'Reset two-factor sign-in of {name} (e.g. lost phone)? All sign-ins are ended; afterwards the password is enough and the person can set up two-factor sign-in again.', tf_chip: '2FA', tf_cancel: 'Cancel', err_wrong_password: 'Wrong password.', err_totp_invalid: 'Code wrong or expired.', err_totp_expired: 'Sign-in expired. Please enter username and password again.', err_totp_already: 'Two-factor sign-in is already on.', err_totp_off: 'Two-factor sign-in is not on.', err_totp_no_setup: 'Please choose “Set up” first.', help_login2fa_t: 'Protecting your sign-in (two-factor)', help_login2fa_s: 'More → My account → Two-factor sign-in → Set up: enter your password, scan the QR code with an authenticator app on your phone, enter the 6-digit code → Turn on.|After that the app asks for the current code from the authenticator app in addition to the password. A code is valid for 30 seconds and only once; if the phone clock is wrong, the code will not match.|Print the recovery codes shown or keep them safe: each works once if the phone is missing. New recovery codes can be created at any time under My account (the old ones then become invalid).|Phone lost and no recovery codes left? The owner can reset two-factor sign-in under More → Users; this ends all sign-ins. Never pass on codes or recovery codes.|New device: if someone signs in to your account on a device that is new for your account, you receive the notification “New sign-in on another device” (device and time). If it was not you: under My account → My sign-ins (devices) sign out that device and change your password. The very first sign-in and sign-ins on known devices do not trigger a notification. The known devices are listed below: “Forget” an old or sold phone there – if someone then signs in on it, the alert comes again.' });
