Object.assign(STRINGS.uk, { search_title: 'Пошук', search_ph: 'Номер авто, VIN, номер заявки, номер справи, запчастина або текст', search_hint: 'Щонайменше 2 символи – шукає транспорт (номер, VIN, причіп, виробник, модель) і заявки, залежно від ролі також штрафи (номер справи, орган) і склад запчастин.', search_more: 'Перші {n} з {m} результатів – уточніть пошук.', search_more_cases: 'Перші {n} заявок – є ще інші.', search_all_cases: 'Показати всі в «Заявках»' });
