Object.assign(STRINGS.de, { end_assign_confirm: 'Zuordnung von {name} zu {plate} jetzt beenden? Das Fahrzeug erscheint dann nicht mehr unter „Mein Fahrzeug“; die Fahrerermittlung bei Bußgeldern nutzt den gespeicherten Zeitraum.', deactivate_confirm: 'Konto von {name} deaktivieren? Die Person wird sofort auf allen Geräten abgemeldet und kann sich nicht mehr anmelden. Vorgänge, Daten und Protokoll bleiben erhalten; „Aktivieren“ macht es rückgängig.', ue_edit: 'Bearbeiten', ue_title: 'Konto bearbeiten: {name}', ue_confirm: 'Rolle bzw. Umgebung von {name} ändern? Alle Anmeldungen und Push-Geräte der Person werden beendet; sie meldet sich danach neu an. Die Änderung steht im Protokoll.', ue_none: 'Keine Änderung.', ue_saved_ended: 'Gespeichert – Anmeldungen und Push-Geräte der Person wurden beendet.' });
Object.assign(STRINGS.uk, { end_assign_confirm: 'Завершити призначення {name} на {plate} зараз? Транспорт більше не відображатиметься в «Мій транспорт»; для визначення водія у штрафах використовується збережений період.', deactivate_confirm: 'Деактивувати акаунт {name}? Особу буде одразу виведено з усіх пристроїв, і вона більше не зможе увійти. Заявки, дані та журнал зберігаються; «Активувати» скасовує це.', ue_edit: 'Редагувати', ue_title: 'Редагувати акаунт: {name}', ue_confirm: 'Змінити роль або середовище для {name}? Усі входи та Push-пристрої цієї особи буде завершено; після цього вона входить знову. Зміну зафіксовано в журналі.', ue_none: 'Змін немає.', ue_saved_ended: 'Збережено – входи та Push-пристрої цієї особи завершено.' });
